router.beforeEach(async (to, from, next) => {
  if (to.meta.title) {
    // ✅ 用 nextTick 延迟执行，不阻塞跳转
    await nextTick();
    versionTood.isNewVersion();
    document.title = to.meta.title as string;
  }
  next();
});

export default router