<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import { showToast, showConfirmDialog } from 'vant'

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const userInfo = ref('')
const type = ref(
  {
	1:"A",
	2:"B",
	3:"C",
	4:"D"
  }
)
const showNav = ref(false) 
const showUser = ref(false)
const  wins = ref(0)
interface Props {
  istop: number
  title: string | null
}

const props = defineProps<Props>()
const param = ref({
	account:0, //用户管理
	personal:0, //个人资料
	game:0, //游戏管理
	dashboard:0, //财务报表
	record:0, //开奖记录
	inner:0, //内部管理
	bet:0, //即时注单
	bet1:0, //收付统计
	odds:0, //赔率设置
	autocontrol:0, //自动降赔
	autobetcontrol:0, //货量降赔
	manualcontrol:0, //手动降赔
	memberdownodds:0, //会员降倍
	automatic:0,
	sdbu:0, // 手动补货
	sqroom:0,
})
// 生命周期
onMounted(() => {
	// 读取本地存储的开关状态
	showNav.value = false;
	userInfo.value = JSON.parse(localStorage.getItem('userInfo')) 
	const pas = localStorage.getItem('changePwds')
	const coks = localStorage.getItem('auuids')
	if (coks&&pas == '2') {
		getUserInfo();
		if(userInfo.value){
			let ts = userInfo.value
			if(ts.role==4){
				ts.layer = res.data.layer-1;
			}
			let str1 = ts;
			if (str1.handicap&&str1.handicap.search(",") != -1) {
				let strs = str1.handicap.split(",");
				str1.handicapList = strs;
			}else{
				str1.handicapList = [];
			}
			let oddType = str1.handicapList;
			if(oddType.length>0){
				let str = ''; 
				oddType.forEach(item=> {
					str +=type.value[item]+',';
				});
				str1.handicaps = str.substring(0,str.length-1);
			}
		}else{
			getUlist(); 
		}
	}
})
const getAvatarIcon = (): string => {
	const picId = userInfo?.value?.picId
	if (picId && picId > 0 && picId < 31) {
		return new URL(`../../assets/images/avatar/au_${picId}.png`, import.meta.url).href
	}
	return new URL(`../../assets/images/avatar/au_1.png`, import.meta.url).href
}
const getTodaySwingsClass = (): string => {
	const swings = wins.value
	if (swings < 0) return 'rds'
	return 'bus'
}
const pmenuTab = () => {
	showNav.value = false
}
const sidTab = () => {
	showNav.value = true;
	if (showNav.value) {
		getUserwin()
	}
}
const goBack = () =>{
	router.push('/home');
}
const navTo = (url) =>{
	const path = route.path
	if (url == path) {
		showNav.value = false
	} else {
		router.push(url)
	}

}

// API 请求方法
const getUserwin = async () => {
	try {
		const res = await userStore.getslotry()
		wins.value = res.data.toDayWin
	} catch (error) {
		console.log('获取用户余额失败:', error)
	}
}

const getUserInfo = async () => {
	try {
		let res = [];
		const cachedMenu = userTime.safeJSONParse(localStorage.getItem('menus'));
		if (cachedMenu!=1) {
		  res = cachedMenu;
		}
		if (res.length === 0) {
			res = await userStore.getMenu();
			localStorage.setItem('menus', JSON.stringify(res));
		}
		if(userInfo.value.role>2&&userInfo.value.openFlag?.length>0){
			userInfo.value.openFlag.forEach(item=>{
				if(item!=1&&userInfo.value.openFlag.length>0){
					param.automatic=userInfo.value.role==4?0:1;
				}
			})
		}
		localStorage.setItem('menus',JSON.stringify(res))
		res.data.forEach(iten=>{
			switch(iten){
				case 1:
					param.value.sdbu=1;
				break;
				case 4:
				   param.value.bet=1;
				break;
				case 5:
					param.value.chart=1;
				break;
				case 6:
					param.value.account=1;
				break;
				case 7:
					param.value.odds=1;
				break;
				case 8:
					param.value.personal=1;
				break;
				case 9:
					param.value.dashboard=1;
				break;
				case 10:
					param.value.record=1;
				break;
				case 11:
					param.value.autobetcontrol=1;
				break;
				case 12:
					param.value.memberdownodds=1;
				break;
				case 13:
					param.value.autocontrol=1;
				break;
				case 14:
					param.value.inner = 1;
				break;
				case 15:
					param.value.manualcontrol = 1;
				break;
				case 17:
					param.value.sqroom = 1;
				break;
			}
		});
		appStore.setSettings(param);
	} catch (error) {
		console.log('获取用户信息失败:', error)
	}
}
const logout = async () => {
	try {
		await showConfirmDialog({
			title: '确定退出登录？',
			messageAlign: 'center',  // 设置 message 居中
			width: '85vw',  
		})
		await userStore.logout()
		localStorage.clear();
		router.push('/')
	} catch {
		// 取消退出
	}
}

const getWins = async() =>{
	try {
		let res = await userStore.getTodaySwings()
		wins.value = res.data.winToday;
	} catch {
		// 取消退出
	}
}
const getUlist = async() =>{
	try {
		let res = await userStore.personaList()
		if(res.data.role==4){
			res.data.layer = res.data.layer-1;
		}
		let str1 = res.data;
		if (str1.handicap&&str1.handicap.search(",") != -1) {
			let strs = str1.handicap.split(",");
			str1.handicapList = strs;
		}else{
			str1.handicapList = [];
		}
		let oddType = str1.handicapList;
		if(oddType.length>0){
			let str = ''; 
			oddType.forEach(item=> {
				str +=type.value[item]+',';
			});
			str1.handicaps = str.substring(0,str.length-1);
		}
		userInfo.value = str1;
	} catch {
		// 取消退出
	}
}
const menuTabs = (num) => {
	showNav.value = false;
	let routes = {
		0:'/home',
		1: '/payMents',
		2: '/UserManage',
		3: '/ReportQuery',
		4: '/twoWeek',
		5: '/lotMkHistory',
		6: '/autoBuHuo',
		7: '/memberOdds',
		8: '/HuoJiangPei',
		9: '/AutoJiangPei',
		10: '/AddRoom',
		11: '/notice',
		12: '/changePwd',
		13: '/Personal',
		14: '/kpjbJiangPei'
	}
	const path = routes[num]
	if (path) {
		setTimeout(()=>{
          router.push(path)
		},100)
	}
}
onUnmounted(() => {
	showNav.value = false;
})
</script>
