import dayjs from "dayjs"
import { useAppStore } from '@/store/index'
import { computed } from "vue"

// 使用 Composition API 创建时间工具函数
export const useTimeUtils = () => {
  const store = useAppStore()
  
  const timeFormat = (str) => {
    return dayjs.unix(str).format("YYYY-MM-DD HH:mm:ss")
  }

  const yesterday = (str) => {
    return dayjs(str).add(-1, 'day').format("YYYY-MM-DD")
  }

  const toDays = (str) => {
    return dayjs(str).format("YYYY-MM-DD")
  }

  // 时间差-秒数
  const timeDiff = (endTime) => {
    const statTime = dayjs().format("YYYY-MM-DD HH:mm:ss")
    const m1 = dayjs(endTime)
    const m2 = dayjs(statTime)
    return m1.diff(m2, "second")
  }

  const timelist = (str) => {
    return dayjs(str).format("HH:mm:ss")
  }
  const timehm = (str) =>{
	  const time = dayjs(str).format("HH:mm")
	  return time
	}
  // 当前日期
  const dateNow = (str) => {
    return dayjs(str).format("YYYY-MM-DD")
  }

  // 倒计时时间
  const timeSet = (time) => {
    let result = ''
    
    if (time <= 0) return 'result'

    let theTime = parseInt(time)
    let middle = 0 // 分
    let hour = 0 // 小时

    if (theTime > 60) {
      middle = Math.floor(theTime / 60)
      theTime = theTime % 60
      if (middle > 60) {
        hour = Math.floor(middle / 60)
        middle = middle % 60
      }
    }

    let t1 = theTime < 10 ? `0${theTime}` : `${theTime}`
    let t2 = middle > 0 ? (middle < 10 ? `0${middle}` : `${middle}`) : "00"
    let t3 = hour > 0 ? (hour < 10 ? `0${hour}` : `${hour}`) : "00"
    result = t3+':'+t2+':'+t1;
    return result
  }

  const count = (i) => {
    let list =[];
    for(var j=i;j>i-12;j--){
      let k='';
      if(j<=0){
        k = j+12
      }else{
        k=j
      }
      list.push(k)
    }
    const updatedZodiac = store.zodiac.map((item, index) => ({
      ...item,
      sort: list[index]
    }))

    localStorage.setItem("marksum", JSON.stringify(updatedZodiac))
  }

  const sortKey = (array, key) => {
    return [...array].sort((a, b) => {
      const x = a[key]
      const y = b[key]
      return x < y ? -1 : x > y ? 1 : 0
    })
  }
// 对象格式转数组
const objToArr = (data) => {
  const isArr = Array.isArray(data)
  let newArr = []
  if (!isArr) {
    for (let i in data) {
      newArr.push(data[i])
    }
  } else {
    newArr = data
  }
  return newArr
}
const startsWithOne = (id) =>{
  if (!id) return false
  const idStr = String(id) // 确保转换为字符串
  return idStr.startsWith('10')
}
const isDot = (num) => {
  if (!num && num !== 0) return 0
  
  const result = num.toString().includes(".")
  return result ? num.toFixed(2).slice(0, -1) : num
}
const numDot = (num) => {
  if(num){
      let result = (num.toString()).indexOf(".");
      if(result != -1) {
          let t1 =  Math.trunc(num);
          let t  = t1.toString().replace(/(\d)(?=(?:\d{3})+$)/g, "$1,");
          return t
      } else {
          let t1 =  Math.trunc(num);
          let t  = t1.toString().replace(/(\d)(?=(?:\d{3})+$)/g, "$1,");
          return t
      }
  }else{
      return 0;
  }
}
const safeJSONParse = (item, defaultValue = null) =>{
  if (!item || item === 'undefined' || item === 'null') {
    return 1;
  }
  try {
    return JSON.parse(item);
  } catch (e) {
    console.error('JSON parse error:', e);
    return defaultValue;
  }
}

// 当前日期
let getTime = (str) => {
  return dayjs(str).format("HH:mm:ss")
}
  return {
    timeFormat,
    timeDiff,
    dateNow,
    timelist,
    timehm,
    timeSet,
    count,
    numDot,
    isDot,
    sortKey,
    yesterday,
    toDays,
    objToArr,
    startsWithOne,
    getTime,
    safeJSONParse,
  }
}