import axios from 'axios'
import { showToast } from 'vant'
import router from '@/router'


const request = axios.create({
  baseURL: '/api',
  timeout: 30000
})

// 请求拦截器
request.interceptors.request.use(
  (config) => {
    // 添加 token
    config.headers['Access-Control-Allow-Origin'] = '*'
    if(localStorage.getItem('auuids')){
      config.headers['uuid'] = localStorage.getItem('auuids');
    }else{
      if(localStorage.getItem('auuid')){
          config.headers['uuid'] = localStorage.getItem('auuid');
      }
    }
    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// 响应拦截器
request.interceptors.response.use(
  (response) => {
    const { data } = response
    if (data.code === 200) {
      return data
    }else if(data.code === 403) {
      localStorage.clear();
      router.push('/login')
    }else if(data.code === 415) {
      localStorage.clear();
      router.push('/404')
    }  else {
      const tts =  data.message || '请求失败'
      showToast(tts);
      return Promise.reject(data.message)
    }
  },
  (error) => {
    return Promise.reject(error)
  }
)

export default request